const body=typeof $json.body==='string'?JSON.parse($json.body):($json.body||$json);
const diagnosticData=body.diagnosticData&&typeof body.diagnosticData==='object'&&!Array.isArray(body.diagnosticData)?body.diagnosticData:null;
if(!diagnosticData)throw new Error('Нет данных диагностики');
const requestId=String(body.requestId||diagnosticData?.исходный_запрос?.id||'').trim();
if(!requestId)throw new Error('Не выбран запрос');

const clientName=String(body.clientName||diagnosticData?.клиент?.имя||'клиент').trim()||'клиент';
const addressMode=['ty','vy','third'].includes(String(body.addressMode||''))?String(body.addressMode):'ty';

const clean=value=>String(value??'').trim().replace(/\s+/g,' ');
const normalizeVu=value=>clean(value).toLocaleLowerCase('ru-RU')
  .replace(/^[«"'“”„]+|[»"'“”„]+$/g,'')
  .replace(/^я[\s,:;.!?—–-]+/u,'')
  .trim();

function fallbackStrongVu(data){
  const groups=new Map();
  for(const situation of Array.isArray(data.ситуации)?data.ситуации:[]){
    for(const belief of Array.isArray(situation.первичные_убеждения)?situation.первичные_убеждения:[]){
      const primary=clean(belief?.убеждение);
      if(!primary)continue;
      for(const feeling of Array.isArray(belief.вторичные_чувства)?belief.вторичные_чувства:[]){
        const feelingText=clean(feeling?.чувство_или_реакция);
        if(!feelingText)continue;
        for(const deep of Array.isArray(feeling.вторичные_убеждения)?feeling.вторичные_убеждения:[]){
          const vu=clean(deep?.убеждение_или_самоопределение);
          const key=normalizeVu(vu);
          if(!key)continue;
          const level=Math.max(1,Math.min(10,Number(deep?.уровень)||5));
          const group=groups.get(key)||{убеждение:vu,максимальный_уровень:0,повторений:0,ветки:[]};
          if(level>=group.максимальный_уровень)group.убеждение=vu;
          group.максимальный_уровень=Math.max(group.максимальный_уровень,level);
          group.повторений++;
          group.ветки.push({
            ситуация:clean(situation?.ситуация),
            первичное_убеждение:primary,
            вторичное_чувство:feelingText,
            уровень_ВУ:level,
            реакции:(Array.isArray(deep?.инстинктивные_реакции)?deep.инстинктивные_реакции:[])
              .map(x=>clean(x?.реакция)).filter(Boolean)
          });
          groups.set(key,group);
        }
      }
    }
  }
  return [...groups.values()]
    .filter(x=>x.максимальный_уровень>=6)
    .sort((a,b)=>(b.повторений>1)-(a.повторений>1)||b.повторений-a.повторений||b.максимальный_уровень-a.максимальный_уровень);
}

const source=Array.isArray(diagnosticData.сильные_ВУ)
  ?diagnosticData.сильные_ВУ:fallbackStrongVu(diagnosticData);
const strongVu=source.filter(x=>x&&clean(x.убеждение)).map(x=>({
  убеждение:clean(x.убеждение),
  максимальный_уровень:Number(x.максимальный_уровень)||0,
  повторений:Number(x.повторений)||1,
  ветки:Array.isArray(x.ветки)?x.ветки:[]
}));
const strongVuNames=strongVu.map(x=>x.убеждение);

let addressInstruction='';
if(addressMode==='vy'){
  addressInstruction='Обращайся к клиенту на «Вы». Оставляй цитаты убеждений в исходной форме «я ...». Не используй «ты» вне цитат.';
}else if(addressMode==='third'){
  addressInstruction='Пиши о клиенте в третьем лице, используя имя «'+clientName+'». Сохраняй убеждения в исходной форме «я ...» внутри кавычек.';
}else{
  addressInstruction='Обращайся к клиенту на «ты». Сохраняй убеждения в исходной форме «я ...» внутри кавычек.';
}

const instructions=String.raw`
Ты — специалист по психологической диагностике. Сформируй ТОЛЬКО две рабочие гипотезы по заполненной таблице: расширенную и короткую.

ГЛАВНОЕ ТРЕБОВАНИЕ — ФОРМА, КАК В ОБРАЗЦЕ.
Никакого психологического заключения, свободного пересказа, дополнительных абзацев, пояснений или рассуждений после основной цепочки.
Расширенная — ОДИН цельный абзац, который можно сказать клиенту вслух. Короткая — ОДНО–ДВА предложения в стиле прямого вывода.
Начинай расширенную словами, соответствующими форме обращения: «В основе твоего запроса лежат глубинные убеждения ...» / «В основе вашего запроса ...» / «В основе запроса [имя] ...».
Затем по порядку: глубинные убеждения → вторичные чувства → первичные убеждения в ситуациях → реальные ситуации → реальные реакции → ТОЧНАЯ формулировка исходного запроса.
Заканчивай расширенную связью исходного запроса с перечисленными глубинными убеждениями, без второго объяснительного абзаца.
Короткая начинается с точного исходного запроса и сразу говорит, на каких глубинных убеждениях он строится. Допустимо завершение «Всё остальное уже разворачивается из них», если оно подходит по смыслу.

ОЧЕНЬ ВАЖНО — ПОНЯТИЕ «СИЛЬНЫЕ ВУ».
Массив сильные_ВУ — это ПОЛНЫЙ список глубинных убеждений из правой колонки «Сильные ВУ» (уровни 6–10, включая скрытые под «Показать ещё»).
Не выбирай только одно или два! В расширенной гипотезе УПОМИНАЙ ВСЕ убеждения из сильные_ВУ, без пропусков и подмены формулировок. Если их шесть — все шесть. Если больше — все. Не вставляй вместо них убеждения с других уровней, не входящие в эту колонку.
Начальное предложение должно перечислить ВСЕ сильные ВУ в кавычках (например, «я ...», «я ...», «я ...»). Если из колонки приходит «беспомощная», допустимо оформить цитату «я беспомощная» — смысл слова не меняй.
Если список пуст, не выдумывай сильные ВУ: сформулируй только осторожную гипотезу по подтверждённым данным.
Не добавляй искусственного ограничения длины: важнее сохранить все ВУ и один связный абзац. Но не повторяй список дважды и не превращай гипотезу в перечисление.
В короткой гипотезе упомяни все те же сильные ВУ компактно. При большом числе ВУ предложение может быть длиннее — главное, чтобы оно оставалось прямым итогом, а не анализом.

СТРУКТУРА ВЕТВЕЙ.
Глубинные ВУ — это только элементы массива сильные_ВУ; первичные убеждения берутся из первичные_убеждения, чувства — из вторичные_чувства, реакции — из инстинктивные_реакции.
Например, «я некрасивая» или «какая-то не такая» могут быть первичными убеждениями, а не глубинными, если отсутствуют в сильные_ВУ. Не переноси их в список глубинных.
Не соединяй разрозненные ветки произвольной причинностью. Если у отдельных ВУ разные чувства или ситуации, сформулируй это кратко и раздельно внутри одного абзаца. Если связи не подтверждены — не додумывай.
Оценки и повторы помогают понять выраженность ВУ, но не дают права объявлять их доказанной причиной.

РИТМ И СТИЛЬ (ТОЛЬКО КОНСТРУКЦИЯ, НЕ КОПИРУЙ СЛОВА):
«В основе всего у тебя лежат глубинные убеждения “[ВСЕ СИЛЬНЫЕ ВУ]”. К ним ты приходишь через [ЧУВСТВА ИЗ ВЕТОК]; эти чувства возникают потому, что в конкретных ситуациях ты воспринимаешь себя как “[ПЕРВИЧНЫЕ УБЕЖДЕНИЯ]”. Это включается, когда [СИТУАЦИИ]. Дальше появляются реакции [РЕАКЦИИ]. И уже вся эта цепочка на поверхности проявляется как [ИСХОДНЫЙ ЗАПРОС]. То есть сам этот запрос строится на этих глубинных убеждениях».
Короткая: «[ИСХОДНЫЙ ЗАПРОС] здесь строится на глубинных убеждениях “[ВСЕ СИЛЬНЫЕ ВУ]”. Всё остальное уже разворачивается из них».
Это только схема синтаксиса. Никогда не копируй конкретные чувства, убеждения, ситуации или реакции из примера, если их нет у клиента.

Не употребляй «в основе прослеживается», «формируется паттерн», «переживание недостаточной ценности», «эти самоопределения», «на их фоне», «может восприниматься как», «вероятно» и другой психологический канцелярит.
Не добавляй рекомендаций, диагнозов, планов, советов или альтернативных гипотез.
Перед ответом проверь, что каждое сильное ВУ присутствует в обоих выводах, первое и последнее звено цепочки не потеряны, а расширенная состоит из одного абзаца.
Не делай неподтверждённых причинных утверждений абсолютной истиной.

ФОРМАТ ВЫВОДА — СТРОГО:

РАСШИРЕННАЯ ГИПОТЕЗА:
[ОДИН абзац, без внутренних подзаголовков, связная цепочка от ВСЕХ сильных ВУ до исходного запроса]

КОРОТКАЯ ГИПОТЕЗА:
[ОДНО–ДВА предложения: исходный запрос → ВСЕ сильные ВУ]

Никакого текста до первого заголовка и после короткой гипотезы.
`+"\nФОРМА ОБРАЩЕНИЯ:\n"+addressInstruction;

const fullData={...diagnosticData,сильные_ВУ:strongVu};
const prompt='ИСХОДНЫЙ ЗАПРОС:\n'+clean(diagnosticData?.исходный_запрос?.формулировка)+
  '\n\nВСЕ СИЛЬНЫЕ ВУ (перечисли КАЖДОЕ в обеих гипотезах):\n'+
  (strongVuNames.length?strongVuNames.map((v,i)=>(i+1)+'. '+v).join('\n'):'Нет ВУ с уровнем 6 и выше')+
  '\n\nСИЛЬНЫЕ ВУ С ВЕТКАМИ:\n'+JSON.stringify(strongVu,null,2)+
  '\n\nПОЛНАЯ ДИАГНОСТИКА:\n'+JSON.stringify(fullData,null,2);

return [{json:{
  accessKey:String(body.accessKey||''),
  clientId:String(body.clientId||''),
  clientName,
  requestId,
  addressMode,
  instructions,
  prompt,
  strongVuNames
}}];

const r=$json||{};
let text=String(r.output_text||'').trim();
if(!text&&Array.isArray(r.output)){
  for(const item of r.output||[]){
    for(const part of item?.content||[]){
      if(part?.type==='output_text'&&part?.text)text+=String(part.text);
    }
  }
}
text=text.trim();
if(!text)throw new Error('OpenAI не вернул текст');
const expanded=(text.match(/РАСШИРЕННАЯ\s+ГИПОТЕЗА\s*:\s*([\s\S]*?)(?=\n\s*КОРОТКАЯ\s+ГИПОТЕЗА\s*:|$)/i)?.[1]||'').trim();
const short=(text.match(/КОРОТКАЯ\s+ГИПОТЕЗА\s*:\s*([\s\S]*?)$/i)?.[1]||'').trim();
return [{json:{reply:text,expandedHypothesis:expanded,shortHypothesis:short}}];
